on conflict (slug) where deleted_at is null do update set
  population = excluded.population,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  match_tokens = excluded.match_tokens,
  updated_at = now();

-- Provenance travels with every row, stamped once rather than repeated 1,059 times.
update seo.geo_place set metadata = metadata || '{"provenance": {"source": "US Census Bureau population estimates (us-cities-top-1k, plotly/datasets)", "url": "https://raw.githubusercontent.com/plotly/datasets/master/us-cities-top-1k.csv", "retrieved": "2026-08-22", "seed": "build_geo_gazetteer_seed.py"}}'::jsonb
  where deleted_at is null and metadata->'provenance' is distinct from '{"provenance": {"source": "US Census Bureau population estimates (us-cities-top-1k, plotly/datasets)", "url": "https://raw.githubusercontent.com/plotly/datasets/master/us-cities-top-1k.csv", "retrieved": "2026-08-22", "seed": "build_geo_gazetteer_seed.py"}}'::jsonb->'provenance';

